import csv
import gzip
import io
import json
import statistics
from datetime import date
from decimal import Decimal
from fastapi import APIRouter, Body, Depends, HTTPException, Query, Response
from pydantic import ValidationError
from sqlalchemy import select
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session


from .integrations import require_access

from .models import Project as Parent, Todo as Child
from .schemas import ProjectCreate as ParentCreate, ProjectRead as ParentRead, ProjectPatch as ParentPatch
from .schemas import TodoCreate as ChildCreate, TodoRead as ChildRead, TodoPatch as ChildPatch
from .schemas import BatchCreate, BatchRead


def create_router(get_session):
    router = APIRouter(dependencies=[Depends(require_access)])

    def require_parent(db, parent_id):
        row = db.get(Parent, parent_id)
        if row is None:
            raise HTTPException(status_code=404, detail="parent not found")
        return row

    def require_child(db, parent_id, child_id):
        require_parent(db, parent_id)
        row = db.scalar(select(Child).where(Child.id == child_id, Child.project_id == parent_id))
        if row is None:
            raise HTTPException(status_code=404, detail="child not found")
        return row

    def integrity_failure(db, exc, missing_parent=False):
        db.rollback()
        code = getattr(exc.orig, "sqlstate", None)
        if code == "23503" and missing_parent:
            raise HTTPException(status_code=404, detail="parent not found") from exc
        if code in {"23503", "23505"}:
            raise HTTPException(status_code=409, detail="relationship or unique value conflict") from exc
        raise exc

    async def workflow_rows(parent_id):
        from starlette.concurrency import run_in_threadpool
        def read():
            from .database import engine
            with Session(engine) as db:
                require_parent(db, parent_id)
                rows = list(db.scalars(select(Child).where(Child.project_id == parent_id).order_by(Child.id).limit(1001)))
                if len(rows) > 1000:
                    raise HTTPException(status_code=413, detail="workflow is limited to 1000 rows")
                return [ChildRead.model_validate(row).model_dump(mode="json") for row in rows]
        return await run_in_threadpool(read)

    async def workflow_import(parent_id, records):
        from starlette.concurrency import run_in_threadpool
        def write():
            from .database import engine
            with Session(engine) as db:
                require_parent(db, parent_id)
                rows = []
                try:
                    for data in records:
                        row = Child(project_id=parent_id, **data.model_dump())
                        db.add(row)
                        db.flush()
                        rows.append(row)
                    db.commit()
                except IntegrityError as exc:
                    integrity_failure(db, exc, True)
                return [ChildRead.model_validate(row).model_dump(mode="json") for row in rows]
        return await run_in_threadpool(write)

    @router.post("/projects", response_model=ParentRead, status_code=201)
    def create_parent(data: ParentCreate, db: Session = Depends(get_session)):
        row = Parent(**data.model_dump())
        db.add(row)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc, False)
        db.refresh(row)
        return row

    @router.get("/projects/{parent_id}", response_model=ParentRead)
    def get_parent(parent_id: int, db: Session = Depends(get_session)):
        return require_parent(db, parent_id)

    @router.get("/projects", response_model=list[ParentRead])
    def list_parent(limIt: int = Query(20, alias="limit", ge=1, le=20), offset: int = Query(0, ge=0), db: Session = Depends(get_session)):
        statement = select(Parent)
        return list(db.scalars(statement.order_by(Parent.id).limit(limIt).offset(offset)))

    @router.patch("/projects/{parent_id}", response_model=ParentRead)
    def patch_parent(parent_id: int, data: ParentPatch, db: Session = Depends(get_session)):
        row = require_parent(db, parent_id)
        for name, value in data.model_dump(exclude_unset=True).items():
            setattr(row, name, value)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        db.refresh(row)
        return row

    @router.delete("/projects/{parent_id}", status_code=204)
    def delete_parent(parent_id: int, db: Session = Depends(get_session)):
        row = require_parent(db, parent_id)
        db.delete(row)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        return Response(status_code=204)

    @router.post("/projects/{parent_id}/todos", response_model=ChildRead, status_code=201)
    def create_child(parent_id: int, data: ChildCreate, db: Session = Depends(get_session)):
        require_parent(db, parent_id)
        row = Child(project_id=parent_id, **data.model_dump())
        db.add(row)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc, True)
        db.refresh(row)
        return row

    @router.get("/projects/{parent_id}/todos/{child_id}", response_model=ChildRead)
    def get_child(parent_id: int, child_id: int, db: Session = Depends(get_session)):
        return require_child(db, parent_id, child_id)

    @router.get("/projects/{parent_id}/todos", response_model=list[ChildRead])
    def list_child(parent_id: int, completed: bool | None = None, before: date | None = None, limIt: int = Query(20, alias="limit", ge=1, le=100), offset: int = Query(0, ge=0), db: Session = Depends(get_session)):
        require_parent(db, parent_id)
        statement = select(Child).where(Child.project_id == parent_id)
        if completed is not None:
            statement = statement.where(Child.completed == completed)
        if before is not None:
            statement = statement.where(Child.due_on < before)
        return list(db.scalars(statement.order_by(Child.id).limit(limIt).offset(offset)))

    @router.patch("/projects/{parent_id}/todos/{child_id}", response_model=ChildRead)
    def patch_child(parent_id: int, child_id: int, data: ChildPatch, db: Session = Depends(get_session)):
        row = require_child(db, parent_id, child_id)
        for name, value in data.model_dump(exclude_unset=True).items():
            setattr(row, name, value)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        db.refresh(row)
        return row

    @router.delete("/projects/{parent_id}/todos/{child_id}", status_code=204)
    def delete_child(parent_id: int, child_id: int, db: Session = Depends(get_session)):
        row = require_child(db, parent_id, child_id)
        db.delete(row)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        return Response(status_code=204)

    @router.post("/projects/with-children", response_model=BatchRead, status_code=201)
    def create_batch(data: BatchCreate, db: Session = Depends(get_session)):
        parent = Parent(**data.parent.model_dump())
        children = []
        try:
            db.add(parent)
            db.flush()
            for item in data.children:
                child = Child(project_id=parent.id, **item.model_dump())
                db.add(child)
                db.flush()
                children.append(child)
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        db.refresh(parent)
        for child in children:
            db.refresh(child)
        return {"parent": parent, "children": children}

    @router.get("/projects" + "/{parent_id}/export")
    async def export_rows(parent_id: int):
        rows = await workflow_rows(parent_id)
        content = json.dumps(rows, ensure_ascii=False, allow_nan=False, separators=(",", ":")).encode()
        return Response(content, media_type="application/json")

    return router


from fastapi import FastAPI, HTTPException
from .integrations import auth_router, object_router
from .database import engine, get_session
from sqlalchemy import text
from sqlalchemy.exc import SQLAlchemyError

app = FastAPI()
app.include_router(auth_router)
app.include_router(object_router)
app.include_router(create_router(get_session))

@app.get("/healthz")
def healthz():
    try:
        with engine.connect() as connection:
            connection.execute(text("SELECT 1"))
    except SQLAlchemyError as exc:
        raise HTTPException(status_code=503, detail="database unavailable") from exc
    return {"status": "ok"}

