from .schemas import CatalogCreate as ParentCreate, CatalogRead as ParentRead, CatalogPatch as ParentPatch
from .schemas import ProductCreate as ChildCreate, ProductRead as ChildRead, ProductPatch as ChildPatch
from .schemas import BatchCreate, BatchRead


def create_router(get_session):
