from datetime import date, datetime
from pydantic import BaseModel, ConfigDict, Field, model_validator


class BoundedInput(BaseModel):
    model_config = ConfigDict(extra="forbid", allow_inf_nan=False)

    @model_validator(mode="after")
    def bounded_values(self):
        for name in self.model_fields_set:
            value = getattr(self, name)
            if isinstance(value, str) and len(value) > 255:
                raise ValueError("strings must have at most 255 characters")
            if type(value) is int and not -(2**31) <= value < 2**31:
                raise ValueError("integers must fit signed 32 bits")
        return self


class CatalogCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    name: str
    code: str


class CatalogRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    name: str
    code: str
    created_at: datetime
    updated_at: datetime


class CatalogPatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    name: str | None = None
    code: str | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "CatalogPatch":
        nullable = {
            "name": False,
            "code": False,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class ProductCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    sku: str
    name: str
    weight: float | None = None
    listed: bool = False
    object_key: str | None = None


class ProductRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    catalog_id: int
    sku: str
    name: str
    weight: float | None
    listed: bool
    object_key: str | None
    created_at: datetime
    updated_at: datetime


class ProductPatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    sku: str | None = None
    name: str | None = None
    weight: float | None = None
    listed: bool | None = None
    object_key: str | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "ProductPatch":
        nullable = {
            "sku": False,
            "name": False,
            "weight": True,
            "listed": False,
            "object_key": True,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class BatchCreate(BaseModel):
    model_config = ConfigDict(extra="forbid")
    parent: CatalogCreate
    children: list[ProductCreate] = Field(min_length=1, max_length=20)


class BatchRead(BaseModel):
    parent: CatalogRead
    children: list[ProductRead]

