        return row

    @router.get("/recipes/{parent_id}/ingredients/{child_id}", response_model=ChildRead)
    def get_child(parent_id: int, child_id: int, db: Session = Depends(get_session)):
        return require_child(db, parent_id, child_id)

    @router.get("/recipes/{parent_id}/ingredients", response_model=list[ChildRead])
    def list_child(parent_id: int, limIt: int = Query(20, alias="limit", ge=1, le=100), offset: int = Query(0, ge=0), db: Session = Depends(get_session)):
        require_parent(db, parent_id)
        statement = select(Child).where(Child.recipe_id == parent_id)
        return list(db.scalars(statement.order_by(Child.id).limit(limIt).offset(offset)))

    @router.patch("/recipes/{parent_id}/ingredients/{child_id}", response_model=ChildRead)
    def patch_child(parent_id: int, child_id: int, data: ChildPatch, db: Session = Depends(get_session)):
        row = require_child(db, parent_id, child_id)
        for name, value in data.model_dump(exclude_unset=True).items():
            setattr(row, name, value)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        db.refresh(row)
        return row

    @router.delete("/recipes/{parent_id}/ingredients/{child_id}", status_code=204)
    def delete_child(parent_id: int, child_id: int, db: Session = Depends(get_session)):
        row = require_child(db, parent_id, child_id)
        db.delete(row)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        return Response(status_code=204)

    @router.post("/recipes/with-children", response_model=BatchRead, status_code=201)
    def create_batch(data: BatchCreate, db: Session = Depends(get_session)):
        parent = Parent(**data.parent.model_dump())
        children = []
        try:
            db.add(parent)
            db.flush()
            for item in data.children:
                child = Child(recipe_id=parent.id, **item.model_dump())
                db.add(child)
                db.flush()
                children.append(child)
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        db.refresh(parent)
        for child in children:
            db.refresh(child)
        return {"parent": parent, "children": children}

    @router.get("/recipes" + "/{parent_id}/export")
    async def export_rows(parent_id: int):
        rows = await workflow_rows(parent_id)
        totals = {}
        for row in rows:
            if row["quantity"] is not None:
                key = row["unit"]
                totals[key] = totals.get(key, Decimal(0)) + Decimal(str(row["quantity"]))
        return {"totals": {key: str(value) for key, value in sorted(totals.items())}}

    return router


