import firebase_admin
from firebase_admin import auth as firebase_auth, credentials as firebase_credentials
from google.auth.credentials import AnonymousCredentials
from google.auth.exceptions import GoogleAuthError
from firebase_admin import exceptions as firebase_errors

FIREBASE_PROJECT = setting("FIREBASE_PROJECT_ID")
firebase_emulator = local_override("FIREBASE_AUTH_EMULATOR_HOST")


class LocalFirebaseCredential(firebase_credentials.Base):
    def get_credential(self):
        return AnonymousCredentials()


firebase_app = firebase_admin.initialize_app(
    LocalFirebaseCredential() if firebase_emulator else None,
    options={"projectId": FIREBASE_PROJECT},
    name=APPLICATION,
)


def authenticate(request):
    try:
        claims = firebase_auth.verify_id_token(bearer(request), app=firebase_app, check_revoked=True)
        now = time.time()
        if any(type(claims.get(key)) not in {int, float} or not math.isfinite(claims[key]) for key in ("exp", "iat", "auth_time")) or claims["exp"] <= now or claims["iat"] > now or claims["auth_time"] > now:
            raise ValueError("expired or invalid token time claims")
    except (firebase_auth.InvalidIdTokenError, firebase_auth.ExpiredIdTokenError, firebase_auth.RevokedIdTokenError, firebase_auth.UserDisabledError, firebase_auth.UserNotFoundError, ValueError, KeyError, TypeError) as exc:
        raise unauthorized() from exc
    except (firebase_errors.FirebaseError, GoogleAuthError) as exc:
        raise HTTPException(status_code=503, detail="authentication provider unavailable") from exc
    return {"sub": claims["uid"], "role": claims.get("role", "reader")}


import hashlib
import re

from fastapi import Path as ApiPath
from starlette.concurrency import run_in_threadpool

MAX_OBJECT_BYTES = 1048576
object_router = APIRouter(prefix="/objects", dependencies=[Depends(require_access)])


class ObjectMissing(Exception):
    pass


class ObjectExists(Exception):
    pass


class ObjectUnavailable(Exception):
    pass


def object_response_error(error):
    if isinstance(error, ObjectMissing):
        raise HTTPException(status_code=404, detail="object not found") from error
    raise HTTPException(status_code=503, detail="object storage unavailable; retry the request") from error


@object_router.put("/{key}")
async def upload_object(request: Request, key: str = ApiPath(pattern=r"^[A-Za-z0-9_-]{1,80}$")):
    body = bytearray()
    async for chunk in request.stream():
        body.extend(chunk)
        if len(body) > MAX_OBJECT_BYTES:
            raise HTTPException(status_code=413, detail="object exceeds 1 MiB")
    if not body:
        raise HTTPException(status_code=422, detail="empty object")
    body = bytes(body)
    sha256 = hashlib.sha256(body).hexdigest()
    try:
        await run_in_threadpool(storage_put, key, body, sha256)
    except ObjectExists:
        try:
            existing = await run_in_threadpool(storage_get, key)
        except (ObjectMissing, ObjectUnavailable) as exc:
            object_response_error(exc)
        if existing != body:
            raise HTTPException(status_code=409, detail="object key already contains different data")
    except ObjectUnavailable as exc:
        object_response_error(exc)
    return {"key": key, "size": len(body), "sha256": sha256}


@object_router.get("/{key}")
def download_object(key: str = ApiPath(pattern=r"^[A-Za-z0-9_-]{1,80}$")):
    try:
        body = storage_get(key)
    except (ObjectMissing, ObjectUnavailable) as exc:
        object_response_error(exc)
    if len(body) > MAX_OBJECT_BYTES:
        raise HTTPException(status_code=413, detail="stored object exceeds 1 MiB")
    return Response(content=body, media_type="application/octet-stream", headers={"X-Content-SHA256": hashlib.sha256(body).hexdigest()})


@object_router.delete("/{key}", status_code=204)
def remove_object(key: str = ApiPath(pattern=r"^[A-Za-z0-9_-]{1,80}$")):
    try:
        storage_delete(key)
    except ObjectMissing:
        pass
    except ObjectUnavailable as exc:
        object_response_error(exc)
    return Response(status_code=204)


from google.cloud import storage as gcs_storage
from google.auth.credentials import AnonymousCredentials as GCSAnonymousCredentials
from google.api_core import exceptions as gcs_errors
import requests as gcs_requests

GCS_BUCKET = setting("GCS_BUCKET")
gcs_endpoint = local_override("STORAGE_EMULATOR_HOST")
gcs_client = gcs_storage.Client(project=setting("GCS_PROJECT"), credentials=GCSAnonymousCredentials() if gcs_endpoint else None)
gcs_bucket = gcs_client.bucket(GCS_BUCKET)


def storage_put(key, body, sha256):
    blob = gcs_bucket.blob(key)
    blob.metadata = {"sha256": sha256}
    try:
        blob.upload_from_string(body, content_type="application/octet-stream", if_generation_match=0, timeout=5, retry=None)
    except (gcs_errors.PreconditionFailed, gcs_errors.Conflict) as exc:
        raise ObjectExists() from exc
    except (gcs_errors.GoogleAPIError, gcs_requests.RequestException) as exc:
        raise ObjectUnavailable() from exc


def storage_get(key):
    try:
        return gcs_bucket.blob(key).download_as_bytes(start=0, end=MAX_OBJECT_BYTES, timeout=5, retry=None)
    except gcs_errors.NotFound as exc:
        raise ObjectMissing() from exc
    except (gcs_errors.GoogleAPIError, gcs_requests.RequestException) as exc:
        raise ObjectUnavailable() from exc


def storage_delete(key):
    try:
        gcs_bucket.blob(key).delete(timeout=5, retry=None)
    except gcs_errors.NotFound as exc:
        raise ObjectMissing() from exc
    except (gcs_errors.GoogleAPIError, gcs_requests.RequestException) as exc:
        raise ObjectUnavailable() from exc

