import json
import os
from urllib.parse import urlsplit

from fastapi import APIRouter, Depends, HTTPException, Request, Response

APPLICATION = "app_surveys"
TEST_MODE = os.environ.get("APP_ENV") == "test"
auth_router = APIRouter()


def setting(name):
    value = os.environ.get(name, "")
    if not value:
        raise RuntimeError(name + " is required")
    return value


def local_override(name):
    value = os.environ.get(name)
    if value:
        parsed = urlsplit(value if "://" in value else "http://" + value)
        if not TEST_MODE or parsed.hostname not in {"127.0.0.1", "localhost", "::1"} or parsed.username or parsed.password or parsed.scheme not in {"http", "https"}:
            raise RuntimeError(name + " is allowed only for local test services")
    return value


def unauthorized():
    return HTTPException(status_code=401, detail="invalid or expired authentication", headers={"WWW-Authenticate": "Bearer"})


def bearer(request):
    scheme, separator, token = request.headers.get("authorization", "").partition(" ")
    if scheme.lower() != "bearer" or not separator or not token or len(token) > 16384:
        raise unauthorized()
    return token


def require_identity(request: Request):
    identity = authenticate(request)
    if not isinstance(identity.get("sub"), str) or not identity["sub"]:
        raise unauthorized()
    return identity


def require_access(request: Request, identity=Depends(require_identity)):
    if request.method not in {"GET", "HEAD", "OPTIONS"} and identity.get("role", "reader") != "editor":
        raise HTTPException(status_code=403, detail="editor role required")
    return identity


@auth_router.get("/auth/me")
def who_am_i(identity=Depends(require_identity)):
    return {key: identity[key] for key in ("sub", "role", "csrf") if key in identity}


import math
import time

import firebase_admin
from firebase_admin import auth as firebase_auth, credentials as firebase_credentials
from google.auth.credentials import AnonymousCredentials
from google.auth.exceptions import GoogleAuthError
from firebase_admin import exceptions as firebase_errors

FIREBASE_PROJECT = setting("FIREBASE_PROJECT_ID")
firebase_emulator = local_override("FIREBASE_AUTH_EMULATOR_HOST")


class LocalFirebaseCredential(firebase_credentials.Base):
    def get_credential(self):
        return AnonymousCredentials()


firebase_app = firebase_admin.initialize_app(
    LocalFirebaseCredential() if firebase_emulator else None,
    options={"projectId": FIREBASE_PROJECT},
    name=APPLICATION,
)


def authenticate(request):
    try:
        claims = firebase_auth.verify_id_token(bearer(request), app=firebase_app, check_revoked=True)
        now = time.time()
        if any(type(claims.get(key)) not in {int, float} or not math.isfinite(claims[key]) for key in ("exp", "iat", "auth_time")) or claims["exp"] <= now or claims["iat"] > now or claims["auth_time"] > now:
            raise ValueError("expired or invalid token time claims")
    except (firebase_auth.InvalidIdTokenError, firebase_auth.ExpiredIdTokenError, firebase_auth.RevokedIdTokenError, firebase_auth.UserDisabledError, firebase_auth.UserNotFoundError, ValueError, KeyError, TypeError) as exc:
        raise unauthorized() from exc
    except (firebase_errors.FirebaseError, GoogleAuthError) as exc:
        raise HTTPException(status_code=503, detail="authentication provider unavailable") from exc
    return {"sub": claims["uid"], "role": claims.get("role", "reader")}


