from fastapi import APIRouter, Depends, HTTPException, Query, Response
from pymongo import ReturnDocument
from pymongo.errors import DuplicateKeyError, PyMongoError

from .database import client, database
from .integrations import require_access
from .models import Experiment as Parent, Observation as Child
from .schemas import ExperimentCreate as ParentCreate, ExperimentRead as ParentRead, ExperimentPatch as ParentPatch
from .schemas import ObservationCreate as ChildCreate, ObservationRead as ChildRead, ObservationPatch as ChildPatch
from .schemas import BatchCreate, BatchRead


def create_router(get_session):
    router = APIRouter(dependencies=[Depends(require_access)])

    def encode(values):
        return {key: datetime.combine(value, time(), timezone.utc) if type(value) is date else value for key, value in values.items()}

    async def transaction(callback):
        try:
            async with client.start_session() as session:
                return await session.with_transaction(callback)
        except DuplicateKeyError as exc:
            raise HTTPException(status_code=409, detail="unique value conflict") from exc
        except PyMongoError as exc:
            raise HTTPException(status_code=503, detail="database unavailable") from exc

    async def require_parent(parent_id, session=None, touch=False):
        if touch:
            row = await Parent.get_pymongo_collection().find_one_and_update({"_id": parent_id}, {"$inc": {"_som_revision": 1}}, session=session)
        else:
            row = await Parent.find_one(Parent.id == parent_id, session=session)
        if row is None:
            raise HTTPException(status_code=404, detail="parent not found")
        return row

    async def require_child(parent_id, child_id, session=None):
        await require_parent(parent_id, session)
        row = await Child.find_one(Child.id == child_id, Child.experiment_id == parent_id, session=session)
        if row is None:
            raise HTTPException(status_code=404, detail="child not found")
        return row

    async def insert(model, values, session):
        # Both the counter and new document are part of the same transaction.
        counter = await database["_som_counters"].find_one_and_update({"_id": model.get_settings().name}, {"$inc": {"value": 1}}, upsert=True, return_document=ReturnDocument.AFTER, session=session)
        now = datetime.now(timezone.utc)
        # BSON stores millisecond precision. Return the same timestamp that a
        # later read will return, including the immediate POST response.
        now = now.replace(microsecond=(now.microsecond // 1000) * 1000)
        row = model(id=counter["value"], created_at=now, updated_at=now, **values)
        await row.insert(session=session)
        return row


    async def workflow_rows(parent_id):
        await require_parent(parent_id)
        rows = await Child.find(Child.experiment_id == parent_id).sort("_id").limit(1001).to_list()
        if len(rows) > 1000:
            raise HTTPException(status_code=413, detail="workflow is limited to 1000 rows")
        return [ChildRead.model_validate(row).model_dump(mode="json") for row in rows]

    async def workflow_import(parent_id, records):
        async def write(session):
            await require_parent(parent_id, session, touch=True)
            return [ChildRead.model_validate(await insert(Child, {"experiment_id": parent_id, **data.model_dump()}, session)).model_dump(mode="json") for data in records]
        return await transaction(write)

    @router.post("/experiments", response_model=ParentRead, status_code=201)
    async def create_parent(data: ParentCreate):
        async def write(session):
            return await insert(Parent, {**data.model_dump()}, session)
        return await transaction(write)

    @router.get("/experiments/{parent_id}", response_model=ParentRead)
    async def get_parent(parent_id: int):
        session = None
        return await require_parent(parent_id, session)

    @router.get("/experiments", response_model=list[ParentRead])
    async def list_parent(limIt: int = Query(20, alias="limit", ge=1, le=20), offset: int = Query(0, ge=0)):
        filters = {}
        return await Parent.find(filters).sort("_id").skip(offset).limit(limIt).to_list()

    @router.patch("/experiments/{parent_id}", response_model=ParentRead)
    async def patch_parent(parent_id: int, data: ParentPatch):
        async def write(session):
            row = await require_parent(parent_id, session)
            changes = encode(data.model_dump(exclude_unset=True))
            if changes:
                changes["updated_at"] = datetime.now(timezone.utc)
                await Parent.get_pymongo_collection().update_one({"_id": row.id}, {"$set": changes}, session=session)
            return await Parent.find_one(Parent.id == row.id, session=session)
        return await transaction(write)

    @router.delete("/experiments/{parent_id}", status_code=204)
    async def delete_parent(parent_id: int):
        async def write(session):
            row = await require_parent(parent_id, session)
            await require_parent(parent_id, session, touch=True)
            if await Child.find_one(Child.experiment_id == parent_id, session=session):
                raise HTTPException(status_code=409, detail="parent has children")
            await row.delete(session=session)
        await transaction(write)
        return Response(status_code=204)

    @router.post("/experiments/{parent_id}/observations", response_model=ChildRead, status_code=201)
    async def create_child(parent_id: int, data: ChildCreate):
        async def write(session):
            await require_parent(parent_id, session, touch=True)
            return await insert(Child, {"experiment_id": parent_id, **data.model_dump()}, session)
        return await transaction(write)

    @router.get("/experiments/{parent_id}/observations/{child_id}", response_model=ChildRead)
    async def get_child(parent_id: int, child_id: int):
        session = None
        return await require_child(parent_id, child_id, session)

    @router.get("/experiments/{parent_id}/observations", response_model=list[ChildRead])
    async def list_child(parent_id: int, verified: bool | None = None, limIt: int = Query(20, alias="limit", ge=1, le=100), offset: int = Query(0, ge=0)):
        filters = {"experiment_id": parent_id}
        await require_parent(parent_id)
        if verified is not None:
            filters["verified"] = verified
        return await Child.find(filters).sort("_id").skip(offset).limit(limIt).to_list()

    @router.patch("/experiments/{parent_id}/observations/{child_id}", response_model=ChildRead)
    async def patch_child(parent_id: int, child_id: int, data: ChildPatch):
        async def write(session):
            row = await require_child(parent_id, child_id, session)
            changes = encode(data.model_dump(exclude_unset=True))
            if changes:
                changes["updated_at"] = datetime.now(timezone.utc)
                await Child.get_pymongo_collection().update_one({"_id": row.id}, {"$set": changes}, session=session)
            return await Child.find_one(Child.id == row.id, session=session)
        return await transaction(write)

    @router.delete("/experiments/{parent_id}/observations/{child_id}", status_code=204)
    async def delete_child(parent_id: int, child_id: int):
        async def write(session):
            row = await require_child(parent_id, child_id, session)
            await row.delete(session=session)
        await transaction(write)
        return Response(status_code=204)

    @router.post("/experiments/with-children", response_model=BatchRead, status_code=201)
    async def create_batch(data: BatchCreate):
        async def write(session):
            parent = await insert(Parent, data.parent.model_dump(), session)
            children = [await insert(Child, {"experiment_id": parent.id, **item.model_dump()}, session) for item in data.children]
            return {"parent": parent, "children": children}
        return await transaction(write)

    @router.get("/experiments" + "/{parent_id}/export")
    async def export_rows(parent_id: int):
        rows = await workflow_rows(parent_id)
        values = [row["reading"] for row in rows if row["reading"] is not None]
        return {"count": len(values), "mean": statistics.fmean(values) if values else None, "median": statistics.median(values) if values else None, "minimum": min(values) if values else None, "maximum": max(values) if values else None}

    return router


