import json
import os
from urllib.parse import urlsplit

from fastapi import APIRouter, Depends, HTTPException, Request, Response

APPLICATION = "app_documents"
TEST_MODE = os.environ.get("APP_ENV") == "test"
auth_router = APIRouter()


def setting(name):
    value = os.environ.get(name, "")
    if not value:
        raise RuntimeError(name + " is required")
    return value


def local_override(name):
    value = os.environ.get(name)
    if value:
        parsed = urlsplit(value if "://" in value else "http://" + value)
        if not TEST_MODE or parsed.hostname not in {"127.0.0.1", "localhost", "::1"} or parsed.username or parsed.password or parsed.scheme not in {"http", "https"}:
            raise RuntimeError(name + " is allowed only for local test services")
    return value


def unauthorized():
    return HTTPException(status_code=401, detail="invalid or expired authentication", headers={"WWW-Authenticate": "Bearer"})


def bearer(request):
    scheme, separator, token = request.headers.get("authorization", "").partition(" ")
    if scheme.lower() != "bearer" or not separator or not token or len(token) > 16384:
        raise unauthorized()
    return token


def require_identity(request: Request):
    identity = authenticate(request)
    if not isinstance(identity.get("sub"), str) or not identity["sub"]:
        raise unauthorized()
    return identity


def require_access(request: Request, identity=Depends(require_identity)):
    if request.method not in {"GET", "HEAD", "OPTIONS"} and identity.get("role", "reader") != "editor":
        raise HTTPException(status_code=403, detail="editor role required")
    return identity


@auth_router.get("/auth/me")
def who_am_i(identity=Depends(require_identity)):
    return {key: identity[key] for key in ("sub", "role", "csrf") if key in identity}


import hmac
import secrets
import time

import jwt
import redis
import requests
from authlib.integrations.requests_client import OAuth2Session
from authlib.oauth2.rfc6749.errors import OAuth2Error
from fastapi.responses import RedirectResponse

OIDC_CLIENT_ID = setting("GOOGLE_CLIENT_ID")
OIDC_CLIENT_SECRET = setting("GOOGLE_CLIENT_SECRET")
OIDC_REDIRECT_URI = setting("GOOGLE_REDIRECT_URI")
test_issuer = local_override("SOM_TEST_OIDC_ISSUER")
OIDC_ISSUER = test_issuer or "https://accounts.google.com"
OIDC_AUTHORIZE = OIDC_ISSUER + ("/authorize" if test_issuer else "/o/oauth2/v2/auth")
OIDC_TOKEN = OIDC_ISSUER + "/token" if test_issuer else "https://oauth2.googleapis.com/token"
OIDC_JWKS = OIDC_ISSUER + "/jwks" if test_issuer else "https://www.googleapis.com/oauth2/v3/certs"
if not TEST_MODE and urlsplit(OIDC_REDIRECT_URI).scheme != "https":
    raise RuntimeError("GOOGLE_REDIRECT_URI must use HTTPS outside tests")
editor_subjects = json.loads(setting("GOOGLE_EDITOR_SUBJECTS"))
if not isinstance(editor_subjects, list) or any(not isinstance(value, str) or not value for value in editor_subjects):
    raise RuntimeError("GOOGLE_EDITOR_SUBJECTS must be a JSON list of subject strings")
EDITOR_SUBJECTS = set(editor_subjects)
SESSION_COOKIE = "som_" + APPLICATION
BINDING_COOKIE = SESSION_COOKIE + "_login"
REDIS_PREFIX = setting("REDIS_NAMESPACE") + ":" + APPLICATION + ":"
redis_client = redis.Redis.from_url(setting("REDIS_URL"), decode_responses=True, socket_connect_timeout=2, socket_timeout=2)
google_keys = jwt.PyJWKClient(OIDC_JWKS, timeout=5)


def redis_call(method, *args, **kwargs):
    try:
        return getattr(redis_client, method)(*args, **kwargs)
    except redis.RedisError as exc:
        raise HTTPException(status_code=503, detail="session store unavailable") from exc


def oauth_client():
    return OAuth2Session(OIDC_CLIENT_ID, OIDC_CLIENT_SECRET, scope="openid email profile", redirect_uri=OIDC_REDIRECT_URI, token_endpoint_auth_method="client_secret_post", code_challenge_method="S256")


@auth_router.get("/auth/google/login")
def google_login():
    state, nonce, verifier, binding = [secrets.token_urlsafe(32) for _ in range(4)]
    redis_call("set", REDIS_PREFIX + "state:" + state, json.dumps({"nonce": nonce, "verifier": verifier, "binding": binding}), ex=300, nx=True)
    with oauth_client() as client:
        url, _ = client.create_authorization_url(OIDC_AUTHORIZE, state=state, nonce=nonce, code_verifier=verifier)
    response = RedirectResponse(url, status_code=302)
    response.set_cookie(BINDING_COOKIE, binding, max_age=300, httponly=True, secure=not TEST_MODE, samesite="lax")
    return response


@auth_router.get("/auth/google/callback")
def google_callback(request: Request, state: str, code: str):
    if len(state) > 128 or len(code) > 4096:
        raise HTTPException(status_code=400, detail="invalid OAuth callback")
    saved = redis_call("getdel", REDIS_PREFIX + "state:" + state)
    if not saved:
        raise HTTPException(status_code=400, detail="expired or reused OAuth state")
    saved = json.loads(saved)
    if not hmac.compare_digest(saved["binding"], request.cookies.get(BINDING_COOKIE, "")):
        raise HTTPException(status_code=400, detail="OAuth browser binding mismatch")
    try:
        with oauth_client() as client:
            token = client.fetch_token(OIDC_TOKEN, code=code, code_verifier=saved["verifier"], timeout=5)
        encoded = token["id_token"]
        key = google_keys.get_signing_key_from_jwt(encoded).key
        claims = jwt.decode(encoded, key, algorithms=["RS256"], audience=OIDC_CLIENT_ID, issuer=OIDC_ISSUER, options={"require": ["sub", "exp", "iat", "iss", "aud", "nonce"]})
        if not isinstance(claims["nonce"], str) or not hmac.compare_digest(claims["nonce"], saved["nonce"]):
            raise unauthorized()
    except jwt.PyJWKClientConnectionError as exc:
        raise HTTPException(status_code=503, detail="identity provider unavailable") from exc
    except (jwt.InvalidTokenError, jwt.PyJWKClientError, OAuth2Error, KeyError, ValueError) as exc:
        raise unauthorized() from exc
    except requests.RequestException as exc:
        raise HTTPException(status_code=503, detail="identity provider unavailable") from exc
    lifetime = min(3600, int(claims["exp"] - time.time()))
    if lifetime <= 0:
        raise unauthorized()
    session_id = secrets.token_urlsafe(32)
    identity = {"sub": claims["sub"], "role": "editor" if claims["sub"] in EDITOR_SUBJECTS else "reader", "csrf": secrets.token_urlsafe(32)}
    redis_call("set", REDIS_PREFIX + "session:" + session_id, json.dumps(identity), ex=lifetime, nx=True)
    response = Response(content='{"status":"ok"}', media_type="application/json")
    response.set_cookie(SESSION_COOKIE, session_id, max_age=lifetime, httponly=True, secure=not TEST_MODE, samesite="lax")
    response.delete_cookie(BINDING_COOKIE)
    return response


def authenticate(request):
    session_id = request.cookies.get(SESSION_COOKIE, "")
    if not session_id or len(session_id) > 128:
        raise unauthorized()
    saved = redis_call("get", REDIS_PREFIX + "session:" + session_id)
    if not saved:
        raise unauthorized()
    identity = json.loads(saved)
    if request.method not in {"GET", "HEAD", "OPTIONS"} and not hmac.compare_digest(identity["csrf"], request.headers.get("x-csrf-token", "")):
        raise HTTPException(status_code=403, detail="CSRF token required")
    return identity


@auth_router.post("/auth/logout", status_code=204)
def logout(request: Request, identity=Depends(require_identity)):
    redis_call("delete", REDIS_PREFIX + "session:" + request.cookies[SESSION_COOKIE])
    response = Response(status_code=204)
    response.delete_cookie(SESSION_COOKIE)
    return response


import hashlib
import re

from fastapi import Path as ApiPath
from starlette.concurrency import run_in_threadpool

MAX_OBJECT_BYTES = 1048576
object_router = APIRouter(prefix="/objects", dependencies=[Depends(require_access)])


class ObjectMissing(Exception):
    pass


class ObjectExists(Exception):
    pass


class ObjectUnavailable(Exception):
    pass


def object_response_error(error):
    if isinstance(error, ObjectMissing):
        raise HTTPException(status_code=404, detail="object not found") from error
    raise HTTPException(status_code=503, detail="object storage unavailable; retry the request") from error


@object_router.put("/{key}")
async def upload_object(request: Request, key: str = ApiPath(pattern=r"^[A-Za-z0-9_-]{1,80}$")):
    body = bytearray()
    async for chunk in request.stream():
        body.extend(chunk)
        if len(body) > MAX_OBJECT_BYTES:
            raise HTTPException(status_code=413, detail="object exceeds 1 MiB")
    if not body:
        raise HTTPException(status_code=422, detail="empty object")
    body = bytes(body)
    sha256 = hashlib.sha256(body).hexdigest()
    try:
        await run_in_threadpool(storage_put, key, body, sha256)
    except ObjectExists:
        try:
            existing = await run_in_threadpool(storage_get, key)
        except (ObjectMissing, ObjectUnavailable) as exc:
            object_response_error(exc)
        if existing != body:
            raise HTTPException(status_code=409, detail="object key already contains different data")
    except ObjectUnavailable as exc:
        object_response_error(exc)
    return {"key": key, "size": len(body), "sha256": sha256}


@object_router.get("/{key}")
def download_object(key: str = ApiPath(pattern=r"^[A-Za-z0-9_-]{1,80}$")):
    try:
        body = storage_get(key)
    except (ObjectMissing, ObjectUnavailable) as exc:
        object_response_error(exc)
    if len(body) > MAX_OBJECT_BYTES:
        raise HTTPException(status_code=413, detail="stored object exceeds 1 MiB")
    return Response(content=body, media_type="application/octet-stream", headers={"X-Content-SHA256": hashlib.sha256(body).hexdigest()})


@object_router.delete("/{key}", status_code=204)
def remove_object(key: str = ApiPath(pattern=r"^[A-Za-z0-9_-]{1,80}$")):
    try:
        storage_delete(key)
    except ObjectMissing:
        pass
    except ObjectUnavailable as exc:
        object_response_error(exc)
    return Response(status_code=204)


import boto3
from botocore.config import Config
from botocore.exceptions import BotoCoreError, ClientError

S3_BUCKET = setting("S3_BUCKET")
s3_endpoint = local_override("SOM_TEST_S3_ENDPOINT")
s3_options = {"aws_access_key_id": "local-test", "aws_secret_access_key": "local-test"} if s3_endpoint else {}
s3_client = boto3.client("s3", endpoint_url=s3_endpoint, region_name=os.environ.get("AWS_REGION", "us-east-1"), config=Config(connect_timeout=2, read_timeout=5, retries={"max_attempts": 1}, s3={"addressing_style": "path"}), **s3_options)


def s3_error(exc):
    if isinstance(exc, ClientError):
        code = exc.response.get("Error", {}).get("Code")
        if code in {"NoSuchKey", "404"}:
            raise ObjectMissing() from exc
        if code in {"PreconditionFailed", "ConditionalRequestConflict", "412"}:
            raise ObjectExists() from exc
    raise ObjectUnavailable() from exc


def storage_put(key, body, sha256):
    try:
        s3_client.put_object(Bucket=S3_BUCKET, Key=key, Body=body, ContentType="application/octet-stream", Metadata={"sha256": sha256}, IfNoneMatch="*")
    except (BotoCoreError, ClientError) as exc:
        s3_error(exc)


def storage_get(key):
    try:
        result = s3_client.get_object(Bucket=S3_BUCKET, Key=key, Range=f"bytes=0-{MAX_OBJECT_BYTES}")
        with result["Body"] as stream:
            return stream.read(MAX_OBJECT_BYTES + 1)
    except (BotoCoreError, ClientError) as exc:
        s3_error(exc)


def storage_delete(key):
    try:
        s3_client.delete_object(Bucket=S3_BUCKET, Key=key)
    except (BotoCoreError, ClientError) as exc:
        s3_error(exc)

