        row = Child(project_id=parent_id, **data.model_dump())
        db.add(row)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc, True)
        db.refresh(row)
        return row

    @router.get("/projects/{parent_id}/todos/{child_id}", response_model=ChildRead)
    def get_child(parent_id: int, child_id: int, db: Session = Depends(get_session)):
        return require_child(db, parent_id, child_id)

    @router.get("/projects/{parent_id}/todos", response_model=list[ChildRead])
    def list_child(parent_id: int, enabled: bool | None = None, limIt: int = Query(20, alias="limit", ge=1, le=20), offset: int = Query(0, ge=0), db: Session = Depends(get_session)):
        require_parent(db, parent_id)
        statement = select(Child).where(Child.project_id == parent_id)
        if enabled is not None:
            statement = statement.where(Child.enabled == enabled)
        return list(db.scalars(statement.order_by(Child.id).limit(limIt).offset(offset)))

    @router.patch("/projects/{parent_id}/todos/{child_id}", response_model=ChildRead)
    def patch_child(parent_id: int, child_id: int, data: ChildPatch, db: Session = Depends(get_session)):
        row = require_child(db, parent_id, child_id)
        for name, value in data.model_dump(exclude_unset=True).items():
            setattr(row, name, value)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        db.refresh(row)
        return row

    @router.delete("/projects/{parent_id}/todos/{child_id}", status_code=204)
    def delete_child(parent_id: int, child_id: int, db: Session = Depends(get_session)):
        row = require_child(db, parent_id, child_id)
        db.delete(row)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        return Response(status_code=204)

    @router.post("/projects/with-children", response_model=BatchRead, status_code=201)
    def create_batch(data: BatchCreate, db: Session = Depends(get_session)):
        parent = Parent(**data.parent.model_dump())
        children = []
        try:
            db.add(parent)
            db.flush()
            for item in data.children:
                child = Child(project_id=parent.id, **item.model_dump())
                db.add(child)
                db.flush()
                children.append(child)
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        db.refresh(parent)
        for child in children:
            db.refresh(child)
        return {"parent": parent, "children": children}

    @router.post("/projects", response_model=ParentRead, status_code=201)
    def create_parent(data: ParentCreate, db: Session = Depends(get_session)):
        row = Parent(**data.model_dump())
        db.add(row)
        try:
