import json


import os
import unittest
from fastapi.testclient import TestClient
name = os.environ.get("SOM_TEST_DATABASE_NAME", "")
if not name.startswith("som_test_") or name != os.environ.get("MONGODB_DATABASE"):
    raise RuntimeError("tests require an explicitly named isolated MongoDB database")
from app_surveys_optional.app import app


def parent_payload():
    return {
    }


def child_payload():
    return {
    }


class RelatedServiceTest(unittest.TestCase):
    def test_scoped_crud_and_restriction(self):
        with TestClient(app, headers=json.loads(os.environ["TEST_AUTH_HEADERS"]), cookies=json.loads(os.environ.get("TEST_AUTH_COOKIES", "{}"))) as client:
            parent = client.post("/surveys", json=parent_payload())
            self.assertEqual(parent.status_code, 201, parent.text)
            path = "/surveys" + "/" + str(parent.json()["id"])
            children = path + "/questions"
            try:
                child = client.post(children, json=child_payload())
                self.assertEqual(child.status_code, 201, child.text)
                self.assertEqual(child.json()["survey_id"], parent.json()["id"])
                self.assertEqual(client.delete(path).status_code, 409)
                self.assertEqual(client.post("/surveys" + "/with-children", json={"parent": parent_payload(), "children": []}).status_code, 422)
                self.assertEqual(client.patch(children + "/" + str(child.json()["id"]), json={"survey_id": 999}).status_code, 422)
                self.assertEqual(client.delete(children + "/" + str(child.json()["id"])).status_code, 204)
            finally:
                self.assertEqual(client.delete(path).status_code, 204)


if __name__ == "__main__":
    unittest.main()
